create view IF NOT EXISTS HOLIDAY_DIM_V(
	HOLIDAY_KEY,
	DATE_KEY,
	BRAND_ID COMMENT 'campaignInspire recognized brand id. irb when applied to all brands ',
	HOLIDAY_NM COMMENT 'The Name of the Holiday',
	HOLIDAY_DESC COMMENT 'Name of the objective Holiday.',
	SOURCE_SYSTEM_NM COMMENT 'Inspire level project',
	LOAD_ID COMMENT 'This is the User Identifier of the Person or Process that Loaded the Table',
	LOAD_DTTM COMMENT 'The Date/Datetime the Record was Inserted',
	UPDATE_ID COMMENT 'This is the User Identifier of the Person or Process that Updated the Table',
	UPDATE_DTTM COMMENT 'The Date/Datetime the Record was Updated'
) as 
SELECT HOLIDAY_DIM_BV.HOLIDAY_KEY,HOLIDAY_DIM_BV.DATE_KEY,HOLIDAY_DIM_BV.BRAND_ID,HOLIDAY_DIM_BV.HOLIDAY_NM,HOLIDAY_DIM_BV.HOLIDAY_DESC,HOLIDAY_DIM_BV.SOURCE_SYSTEM_NM,HOLIDAY_DIM_BV.LOAD_ID,HOLIDAY_DIM_BV.LOAD_DTTM,HOLIDAY_DIM_BV.UPDATE_ID,HOLIDAY_DIM_BV.UPDATE_DTTM
FROM IDS_DEV.INT_REF_BV.HOLIDAY_DIM_BV ;
create view IF NOT EXISTS HOLIDAY_LIST_V(
	DATE_KEY,
	HOLIDAY_QTY COMMENT 'Holiday Quantity specifies the number of holidays for a given day.',
	HOLIDAY_IND COMMENT 'Holiday Indicator specifies that a given date has a holiday that falls on it.',
	HOLIDAY_LIST_NM COMMENT 'Holiday List Name is a comma delimeted list of holidays for a given day. For example, Lent, Good Friday.',
	HOLIDAY_LIST_LAST_UPDATE_DTTM COMMENT 'Holiday List Last Update Datetime is the latest last update datetime for a given calendar day.'
) COMMENT='Date Holiday View is a displays a concatenated list of holidays for each date.'
 as 
SELECT HOLIDAY_DIM_BV.DATE_KEY,count(Holiday_nm),MAX(iff(HOLIDAY_NM IS NOT NULL,True,False)),listagg(HOLIDAY_NM, ', '),MAX(UPDATE_DTTM)
FROM IDS_DEV.INT_REF_BV.HOLIDAY_DIM_BV 
		GROUP BY date_key;
