create view IF NOT EXISTS TEMP_TEST_MADA(
	BRAND_ID,
	STORE_ID,
	FISCAL_PERIOD_START_DT,
	FISCAL1YRCOMP_PERIOD,
	CALENDAR1YRCOMP_PERIOD,
	CALENDAR2YRCOMP_PERIOD,
	CALENDAR3YRCOMP_PERIOD,
	FISC_1Y_SALES,
	FISC_1Y_TRANS,
	CAL_1Y_SALES,
	CAL_1Y_TRANS,
	CAL_2Y_SALES,
	CAL_2Y_TRANS,
	CAL_3Y_SALES,
	CAL_3Y_TRANS,
	FISCAL_QUARTER_START_DT,
	FISCAL1YRCOMP_QUARTER,
	CALENDAR1YRCOMP_QUARTER,
	CALENDAR2YRCOMP_QUARTER,
	CALENDAR3YRCOMP_QUARTER
) as 
WITH CY_DT AS (
select DATE_ID,  
FISCAL_YEAR_START_DT,
FISCAL_QUARTER_START_DT,
FISCAL_PERIOD_START_DT,
FISCAL1YRCOMP_PERIOD,   
CALENDAR1YRCOMP_PERIOD,
CALENDAR2YRCOMP_PERIOD,
CALENDAR3YRCOMP_PERIOD 
from IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR 
where DATE_ID = cast('2021-12-20' as date)
),
LY_DT AS (
SELECT DISTINCT 
DT.FISCAL_QUARTER_START_DT,
DT.FISCAL_PERIOD_START_DT,
DT.FISCAL1YRCOMP_QUARTER, 
DT.FISCAL1YRCOMP_PERIOD,
DT.CALENDAR1YRCOMP_QUARTER,
DT.CALENDAR1YRCOMP_PERIOD,
DT.CALENDAR2YRCOMP_QUARTER,
DT.CALENDAR2YRCOMP_PERIOD,
DT.CALENDAR3YRCOMP_QUARTER,
DT.CALENDAR3YRCOMP_PERIOD
FROM
IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR DT
INNER JOIN CY_DT
ON DT.FISCAL_YEAR_START_DT = CY_DT.FISCAL_YEAR_START_DT
AND DT.FISCAL_PERIOD_START_DT <= CY_DT.FISCAL_PERIOD_START_DT
AND DT.FISCAL1YRCOMP_PERIOD <= CY_DT.FISCAL1YRCOMP_PERIOD
AND DT.CALENDAR1YRCOMP_PERIOD <= CY_DT.CALENDAR1YRCOMP_PERIOD
AND DT.CALENDAR2YRCOMP_PERIOD <= CY_DT.CALENDAR2YRCOMP_PERIOD
AND DT.CALENDAR3YRCOMP_PERIOD <= CY_DT.CALENDAR3YRCOMP_PERIOD
),
DT AS (
SELECT 
FISCAL_QUARTER_START_DT,
FISCAL_PERIOD_START_DT, 
FISCAL1YRCOMP_QUARTER, 
FISCAL1YRCOMP_PERIOD,
CALENDAR1YRCOMP_QUARTER,
CALENDAR1YRCOMP_PERIOD,
CALENDAR2YRCOMP_QUARTER,
CALENDAR2YRCOMP_PERIOD,
CALENDAR3YRCOMP_QUARTER,
CALENDAR3YRCOMP_PERIOD,
ROW_NUMBER() OVER (PARTITION BY FISCAL1YRCOMP_PERIOD, FISCAL1YRCOMP_QUARTER                 
                   ORDER BY FISCAL1YRCOMP_PERIOD, FISCAL1YRCOMP_QUARTER DESC) AS ROW_NUM             
from LY_DT
QUALIFY ROW_NUM = 1)

SELECT 
    CR.BRAND_ID,
    CR.STORE_ID,
    DT.FISCAL_PERIOD_START_DT,
    DT.FISCAL1YRCOMP_PERIOD,
    DT.CALENDAR1YRCOMP_PERIOD,
    DT.CALENDAR2YRCOMP_PERIOD,
    DT.CALENDAR3YRCOMP_PERIOD,
    (NVL(FISC_1Y.COMP_SALES,0)) AS FISC_1Y_SALES,
    (NVL(FISC_1Y.COMP_TRANS,0)) AS FISC_1Y_TRANS,
    (NVL(CAL_1Y.COMP_SALES,0)) AS CAL_1Y_SALES,
    (NVL(CAL_1Y.COMP_TRANS,0)) AS CAL_1Y_TRANS,
    (NVL(CAL_2Y.COMP_SALES,0)) AS CAL_2Y_SALES,
    (NVL(CAL_2Y.COMP_TRANS,0)) AS CAL_2Y_TRANS,
    (NVL(CAL_3Y.COMP_SALES,0)) AS CAL_3Y_SALES,
    (NVL(CAL_3Y.COMP_TRANS,0)) AS CAL_3Y_TRANS,
    CR.FISCAL_QUARTER_START_DT,
    DT.FISCAL1YRCOMP_QUARTER,
    DT.CALENDAR1YRCOMP_QUARTER,
    DT.CALENDAR2YRCOMP_QUARTER,
    DT.CALENDAR3YRCOMP_QUARTER
FROM 
table(IDH_DEV.SALES.FLASH_SUMMARY_COMP_PAST_PERIODS(cast('2021-12-20' as date))) CR
INNER JOIN DT
ON DT.FISCAL_PERIOD_START_DT = CR.AGG_START_DT
AND CR.STORE_ID = '07272'
LEFT OUTER JOIN 
TABLE(IDH_DEV.SALES.FLASH_SUMMARY_COMP_PAST_PERIODS((select FISCAL1YRCOMP_DATEID 
                                                        from IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR 
                                                        where date_id = cast('2021-12-20' as date))))  FISC_1Y
                                          
ON  CR.STORE_ID = FISC_1Y.STORE_ID 
AND CR.BRAND_ID = FISC_1Y.BRAND_ID
AND DT.FISCAL1YRCOMP_PERIOD = FISC_1Y.AGG_START_DT
AND DT.FISCAL1YRCOMP_QUARTER = FISC_1Y.FISCAL_QUARTER_START_DT
LEFT OUTER JOIN 
TABLE(IDH_DEV.SALES.FLASH_SUMMARY_COMP_PAST_PERIODS((select CALENDAR1YRCOMP_DATEID 
                                                        from IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR 
                                                        where date_id = cast('2021-12-20' as date))))  CAL_1Y
ON  CR.STORE_ID = CAL_1Y.STORE_ID 
AND CR.BRAND_ID = CAL_1Y.BRAND_ID
AND DT.CALENDAR1YRCOMP_PERIOD = CAL_1Y.AGG_START_DT
AND DT.CALENDAR1YRCOMP_QUARTER = CAL_1Y.FISCAL_QUARTER_START_DT
LEFT OUTER JOIN 
TABLE(IDH_DEV.SALES.FLASH_SUMMARY_COMP_PAST_PERIODS((select CALENDAR2YRCOMP_DATEID 
                                                        from IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR 
                                                        where date_id = cast('2021-12-20' as date))))  CAL_2Y
ON  CR.STORE_ID = CAL_2Y.STORE_ID 
AND CR.BRAND_ID = CAL_2Y.BRAND_ID
AND DT.CALENDAR2YRCOMP_PERIOD = CAL_2Y.AGG_START_DT
AND DT.CALENDAR2YRCOMP_QUARTER = CAL_2Y.FISCAL_QUARTER_START_DT
LEFT OUTER JOIN 
TABLE(IDH_DEV.SALES.FLASH_SUMMARY_COMP_PAST_PERIODS((select CALENDAR3YRCOMP_DATEID 
                                                        from IDS_DEV.INT_REF.VW_COMP_CAL_DATE_3YR 
                                                        where date_id = cast('2021-12-20' as date))))  CAL_3Y
ON  CR.STORE_ID = CAL_3Y.STORE_ID 
AND CR.BRAND_ID = CAL_3Y.BRAND_ID
AND DT.CALENDAR3YRCOMP_PERIOD = CAL_3Y.AGG_START_DT
AND DT.CALENDAR3YRCOMP_QUARTER = CAL_3Y.FISCAL_QUARTER_START_DT

WHERE 
CR.NET_SALES IS NOT NULL
AND (CR.comp_sales IS NULL or CR.comp_sales = 0
OR CR.CLOSED_BEFORE_PERIOD_END_FLAG);
