CREATE FUNCTION IF NOT EXISTS CALCULATE_PERCENTAGE("X" NUMBER(38,0), "Y" NUMBER(38,0))
RETURNS NUMBER(5,1)
LANGUAGE SQL
AS '
  CASE 
    WHEN y = 0
    THEN 0
    ELSE 100 * ( x / y )
  END::DECIMAL(5,1)
';